  const levels = [];
  if (!root) {
    return levels;
  }
  let current = [root];
  while (current.length > 0) {
    const values = [];
    const next = [];
    for (const node of current) {
      values.push(node.val);
      if (node.left) {
        next.push(node.left);
      }
      if (node.right) {
        next.push(node.right);
      }
    }
    levels.push(values);
    current = next;
  }
  return levels.reverse();
}

