function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const value = wide => wide ? pick(2001) - 1000 : pick(7) - 3;
  const serialize = root => {
    const out = [];
    const queue = [root];
    for (let q = 0; q < queue.length; q++) {
      const node = queue[q];
      out.push(node ? node.val : null);
      if (node) queue.push(node.left, node.right);
    }
    while (out.length && out[out.length - 1] === null) out.pop();
    return out;
  };
  if (size === 'small' && rand() < 0.08) return [[]];
  if (size === 'large' && rand() < 0.3) {
    // A complete tree uses every slot of the array, so it can hold the full 2000 nodes.
    return [Array.from({ length: 2000 }, () => value(true))];
  }
  const wide = size === 'large' || rand() < 0.5;
  const count = size === 'large' ? 900 + pick(90) : 1 + pick(12);
  const deep = rand() < 0.3;
  const nodes = [{ val: value(wide), left: null, right: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: value(wide), left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  return [serialize(nodes[0])];
}
